<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Ubuntu‑style Desktop</title>
<style>
*{margin:0;padding:0;box-sizing:border-box;}
body,html{width:100%;height:100%;overflow:hidden;font-family:sans-serif;background:#222;color:#eee;}
#desktop{position:absolute;width:100%;height:100%;background:#1a1a1a;}
#taskbar{
  position:absolute;
  bottom:0;left:0;width:100%;
  height:40px;
  background:#111;
  display:flex;
  align-items:center;
  padding:0 10px;
}
button{margin-right:5px;background:#333;color:#eee;border:none;padding:6px 12px;cursor:pointer;}
button:hover{background:#444;}
.window{
  position:absolute;
  width:400px;height:300px;
  background:#2b2b2b;
  border:1px solid #555;
  box-shadow:0 4px 10px rgba(0,0,0,.5);
  display:none;
}
.win-header{
  height:30px;background:#333;cursor:pointer;
  display:flex;align-items:center;padding:0 8px;
}
.win-title{flex-grow:1;color:#ccc;}
.win-close{background:none;border:none;color:#eee;font-weight:bold;cursor:pointer;}
#files-window,#notepad-window{width:500px;height:400px;}
#files-header, #notepad-header{font-size:14px;}
#files-path{margin-left:10px;font-family:monospace;}
.fs-list{padding:10px;background:#2b2b2b;color:#eee;overflow:auto;height:calc(100% - 60px);}
.fs-item{
  padding:4px 8px;
  cursor:pointer;
}
.fs-item:hover{background:#444;}
#files-up{margin-top:5px;font-size:12px;}
/* Tab styles */
.tabs{display:flex;border-bottom:1px solid #555;background:#333;padding:0 4px;}
.tab{
  padding:6px 10px;
  margin-right:2px;
  background:#444;color:#eee;cursor:pointer;
}
.tab.active{background:#555;font-weight:bold;}
#new-tab{margin-left:auto;background:none;border:none;color:#aaa;cursor:pointer;}
#editor{width:100%;height:calc(100% - 40px);background:#1e1e1e;color:#fff;border:none;padding:8px;font-family:monospace;}
</style>
</head>
<body>
<div id="desktop">
  <div id="taskbar">
    <button id="open-files">Files</button>
    <button id="open-notepad">Notepad</button>
  </div>

  <!-- Files Window -->
  <div id="files-window" class="window">
    <div class="win-header" id="files-header">
      <span class="win-title">Files</span>
      <button class="win-close">&times;</button>
    </div>
    <div style="padding:5px;">
      <span id="files-path">/</span>
      <a href="#" id="files-up">[Up]</a>
    </div>
    <div class="fs-list" id="fs-list"></div>
  </div>

  <!-- Notepad Window -->
  <div id="notepad-window" class="window">
    <div class="win-header" id="notepad-header">
      <span class="win-title">Notepad</span>
      <button class="win-close">&times;</button>
    </div>
    <div style="height:calc(100% - 30px);display:flex;">
      <div style="width:200px;overflow:auto;background:#222;">
        <div id="tabs" class="tabs"></div>
        <button id="new-tab">+ New</button>
      </div>
      <textarea id="editor"></textarea>
    </div>
  </div>
</div>

<script>
// ---------- Utility ----------
function makeDraggable(el, handle) {
  let pos = {x:0,y:0,downX:0,downY:0};
  handle.onmousedown = e => {
    e.preventDefault();
    pos.downX = e.clientX;
    pos.downY = e.clientY;
    document.addEventListener('mousemove', move);
    document.addEventListener('mouseup', up);
  };
  function move(e) {
    const dx = e.clientX - pos.downX;
    const dy = e.clientY - pos.downY;
    el.style.left = (el.offsetLeft + dx)+'px';
    el.style.top = (el.offsetTop + dy)+'px';
    pos.downX = e.clientX; pos.downY = e.clientY;
  }
  function up() {
    document.removeEventListener('mousemove', move);
    document.removeEventListener('mouseup', up);
  }
}

// ---------- Files App ----------
const fileStructure = {
  '/': {type:'dir', children:{bin:1, etc:1, home:1, usr:1, var:1}},
  '/home': {type:'dir', children:{user:1}},
  '/home/user': {type:'dir', children:{Documents:1, Downloads:1, Pictures:1}}
};
let currentPath = '/';
const filesWindow = document.getElementById('files-window');
const fsList = document.getElementById('fs-list');
const filesPath = document.getElementById('files-path');
document.getElementById('open-files').onclick = () => {
  showWindow(filesWindow);
};
document.querySelector('#files-window .win-close').onclick = () => hideWindow(filesWindow);

function showWindow(el){el.style.display='block';}
function hideWindow(el){el.style.display='none';}

makeDraggable(filesWindow, document.getElementById('files-header'));

function renderList(){
  fsList.innerHTML='';
  const node = fileStructure[currentPath];
  if (!node || node.type!=='dir') return;
  for(const name in node.children){
    const div=document.createElement('div');
    div.textContent=name;
    div.className='fs-item';
    div.onclick=() => { /* single click: nothing */ };
    div.ondblclick=()=>{
      const newPath = currentPath.endsWith('/')?currentPath+name : currentPath+'/'+name;
      if(fileStructure[newPath]){currentPath=newPath;filesPath.textContent=currentPath;}
      renderList();
    };
    fsList.appendChild(div);
  }
}
document.getElementById('files-up').onclick=e=>{
  e.preventDefault();
  if(currentPath!=='/') {
    const parts=currentPath.split('/').filter(Boolean);
    parts.pop();
    currentPath='/' + parts.join('/');
    filesPath.textContent=currentPath;
    renderList();
  }
};
renderList();

// ---------- Notepad ----------
const tabsEl=document.getElementById('tabs');
const newTabBtn=document.getElementById('new-tab');
const editor=document.getElementById('editor');
let tabs=[];
let activeIndex=0;

function loadTabs(){
  const data=localStorage.getItem('notepad-tabs');
  if(data){
    try{tabs=JSON.parse(data);}catch(e){tabs=[];}
  }
}
function saveTabs(){localStorage.setItem('notepad-tabs',JSON.stringify(tabs));}

function renderTabs(){
  tabsEl.innerHTML='';
  tabs.forEach((t,i)=>{
    const tab=document.createElement('div');
    tab.className='tab'+(i===activeIndex?' active':'');
    tab.textContent=t.title;
    tab.onclick=()=>{activeIndex=i;render();};
    tabsEl.appendChild(tab);
  });
}

function render(){
  renderTabs();
  editor.value = tabs[activeIndex]?tabs[activeIndex].content:'';
}
newTabBtn.onclick=()=>{
  const title='Untitled '+(tabs.length+1);
  tabs.push({title,content:''});
  activeIndex=tabs.length-1;
  render();saveTabs();
};
editor.oninput=()=>{if(tabs[activeIndex]){tabs[activeIndex].content=editor.value;saveTabs();}};
document.getElementById('open-notepad').onclick=()=>{
  showWindow(document.getElementById('notepad-window'));
};
document.querySelector('#notepad-window .win-close').onclick=()=>hideWindow(document.getElementById('notepad-window'));

makeDraggable(document.getElementById('notepad-window'), document.getElementById('notepad-header'));

// ---------- Init ----------
loadTabs();
render();

// ---------- Window Positioning ----------
function centerWindow(el){
  el.style.left = (window.innerWidth - el.offsetWidth)/2 + 'px';
  el.style.top = (window.innerHeight - el.offsetHeight)/2 + 'px';
}
centerWindow(filesWindow);
centerWindow(document.getElementById('notepad-window'));
</script>
</body>
</html>
